\set ON_ERROR_STOP on
do $$ begin if to_regclass('public.website_build_sessions') is null then raise exception 'MISSING_WEBSITE_BUILD_SESSIONS'; end if; end $$;
create function public.website_build_test_assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'TEST FAILED: %',label; end if; raise notice 'PASS %',label; end $$;
select set_config('test.principal','{"userId":"20000000-0000-4000-8000-000000000001","allowedProjectIds":["10000000-0000-4000-8000-000000000001"]}',false);
select set_config('test.create','{"projectId":"10000000-0000-4000-8000-000000000001","agentId":"40000000-0000-4000-8000-000000000001","conversationId":"50000000-0000-4000-8000-000000000001","brief":"Bygg min hemsida","idempotencyKey":"create-1"}',false);
select set_config('test.artifact','__ARTIFACT_JSON__',false);
select set_config('test.session',(website_build_create(current_setting('test.principal')::jsonb,current_setting('test.create')::jsonb)->>'sessionId'),false);
select set_config('test.ref',jsonb_build_object('projectId','10000000-0000-4000-8000-000000000001','sessionId',current_setting('test.session'))::text,false);
select website_build_test_assert(website_build_create(current_setting('test.principal')::jsonb,current_setting('test.create')::jsonb)->>'sessionId'=current_setting('test.session'),'duplicate create is same session');
do $$ begin perform website_build_create(current_setting('test.principal')::jsonb,current_setting('test.create')::jsonb||'{"brief":"Different"}'); raise exception 'TEST FAILED: duplicate create conflict'; exception when unique_violation then raise notice 'PASS duplicate create conflict'; end $$;
select set_config('test.feedback',(website_build_append_feedback(current_setting('test.principal')::jsonb,current_setting('test.ref')::jsonb,'{"idempotencyKey":"f1","text":"Gör rubriken grön","inputSource":"text","viewedRevisionId":null}'::jsonb)->>'id'),false);
select website_build_test_assert(website_build_append_feedback(current_setting('test.principal')::jsonb,current_setting('test.ref')::jsonb,'{"idempotencyKey":"f1","text":"Gör rubriken grön","inputSource":"text","viewedRevisionId":null}'::jsonb)->>'id'=current_setting('test.feedback'),'duplicate feedback is one receipt');
do $$ begin perform website_build_append_feedback(current_setting('test.principal')::jsonb,current_setting('test.ref')::jsonb,'{"idempotencyKey":"f1","text":"Different","inputSource":"text","viewedRevisionId":null}'); raise exception 'TEST FAILED: feedback conflict'; exception when unique_violation then raise notice 'PASS duplicate feedback conflict'; end $$;
select website_build_test_assert((select count(*)=1 from website_build_feedback where session_id=current_setting('test.session')::uuid),'duplicate feedback is one row');
do $$ begin perform website_build_append_feedback(current_setting('test.principal')::jsonb,current_setting('test.ref')::jsonb,'{"idempotencyKey":"foreign-revision","text":"Ändra","inputSource":"text","viewedRevisionId":"90000000-0000-4000-8000-000000000001"}'); raise exception 'TEST FAILED: foreign viewedRevision accepted'; exception when no_data_found then raise notice 'PASS foreign viewedRevision denied'; end $$;
update runs set status='running',claim_id='60000000-0000-4000-8000-000000000001',lease_until=now()+interval '5 minutes' where id=(select current_run_id from website_build_sessions where id=current_setting('test.session')::uuid);
select set_config('test.writer',(select jsonb_build_object('projectId',s.project_id,'sessionId',s.id,'runId',s.current_run_id,'claimId',r.claim_id,'generation',s.generation)::text from website_build_sessions s join runs r on r.id=s.current_run_id where s.id=current_setting('test.session')::uuid),false);
do $$ begin perform website_build_commit_revision(current_setting('test.writer')::jsonb||'{"claimId":"60000000-0000-4000-8000-000000000009"}',current_setting('test.artifact')::jsonb); raise exception 'TEST FAILED: stale claim'; exception when serialization_failure then raise notice 'PASS stale claim fenced'; end $$;
do $$ begin perform website_build_commit_revision(current_setting('test.writer')::jsonb||'{"projectId":"10000000-0000-4000-8000-000000000002"}',current_setting('test.artifact')::jsonb); raise exception 'TEST FAILED: wrong project'; exception when serialization_failure then raise notice 'PASS foreign writer project fenced'; end $$;
do $$ begin perform website_build_commit_revision(current_setting('test.writer')::jsonb||'{"generation":99}',current_setting('test.artifact')::jsonb); raise exception 'TEST FAILED: wrong generation'; exception when serialization_failure then raise notice 'PASS older or unknown generation fenced'; end $$;
update runs set lease_until=now()-interval '1 second' where id=(current_setting('test.writer')::jsonb->>'runId')::uuid;
do $$ begin perform website_build_commit_revision(current_setting('test.writer')::jsonb,current_setting('test.artifact')::jsonb); raise exception 'TEST FAILED: expired lease'; exception when serialization_failure then raise notice 'PASS expired lease fenced'; end $$;
update runs set lease_until=now()+interval '5 minutes' where id=(current_setting('test.writer')::jsonb->>'runId')::uuid;
select set_config('test.v1',(website_build_commit_revision(current_setting('test.writer')::jsonb,current_setting('test.artifact')::jsonb)->>'id'),false);
select website_build_test_assert((select active_preview_revision_id=current_setting('test.v1')::uuid from website_build_sessions where id=current_setting('test.session')::uuid),'revision one is active');
select website_build_test_assert((select count(*)=1 from runs where kind='website.static.build.v1' and status='pending' and input->>'sessionId'=current_setting('test.session')),'feedback arriving during v1 creates exactly one successor');
update runs set status='running',claim_id='60000000-0000-4000-8000-000000000002',lease_until=now()+interval '5 minutes' where id=(select current_run_id from website_build_sessions where id=current_setting('test.session')::uuid);
select set_config('test.writer',(select jsonb_build_object('projectId',s.project_id,'sessionId',s.id,'runId',s.current_run_id,'claimId',r.claim_id,'generation',s.generation)::text from website_build_sessions s join runs r on r.id=s.current_run_id where s.id=current_setting('test.session')::uuid),false);
select website_build_record_interpretation(current_setting('test.writer')::jsonb,jsonb_build_object('items',jsonb_build_array(jsonb_build_object('feedbackId',current_setting('test.feedback'),'summary','Jag gör rubriken grön.','disposition','apply','changeKey','hero.color','supersedesFeedbackIds','[]'::jsonb))));
select website_build_save_candidate(current_setting('test.writer')::jsonb,current_setting('test.artifact')::jsonb);
select website_build_control(current_setting('test.principal')::jsonb,current_setting('test.ref')::jsonb,'{"action":"pause","idempotencyKey":"pause-1"}');
select website_build_test_assert((select status='pausing' from website_build_sessions where id=current_setting('test.session')::uuid),'pause intent is not false acknowledgement');
update runs set status='pending' where id=(select current_run_id from website_build_sessions where id=current_setting('test.session')::uuid);
select website_build_test_assert((select status='pausing' from website_build_sessions where id=current_setting('test.session')::uuid),'pause intent survives a worker retry');
update runs set status='running' where id=(select current_run_id from website_build_sessions where id=current_setting('test.session')::uuid);
do $$ begin perform website_build_commit_revision(current_setting('test.writer')::jsonb,current_setting('test.artifact')::jsonb); raise exception 'TEST FAILED: commit after pause'; exception when object_not_in_prerequisite_state then raise notice 'PASS paused commit refused'; end $$;
select website_build_park(current_setting('test.writer')::jsonb);
select website_build_test_assert((select status='paused' and active_preview_revision_id=current_setting('test.v1')::uuid from website_build_sessions where id=current_setting('test.session')::uuid),'park acknowledges pause and preserves preview');
select website_build_control(current_setting('test.principal')::jsonb,current_setting('test.ref')::jsonb,'{"action":"resume","idempotencyKey":"resume-1"}');
update runs set status='running',claim_id='60000000-0000-4000-8000-000000000003',lease_until=now()+interval '5 minutes' where id=(select current_run_id from website_build_sessions where id=current_setting('test.session')::uuid);
select set_config('test.writer',(select jsonb_build_object('projectId',s.project_id,'sessionId',s.id,'runId',s.current_run_id,'claimId',r.claim_id,'generation',s.generation)::text from website_build_sessions s join runs r on r.id=s.current_run_id where s.id=current_setting('test.session')::uuid),false);
select website_build_test_assert(website_build_snapshot(current_setting('test.writer')::jsonb)->'candidate'->>'sha256'=current_setting('test.artifact')::jsonb->>'sha256','resume retains completed candidate');
select set_config('test.v2',(website_build_commit_revision(current_setting('test.writer')::jsonb,current_setting('test.artifact')::jsonb)->>'id'),false);
select website_build_test_assert((select status='applied' and applied_revision_id=current_setting('test.v2')::uuid from website_build_feedback where id=current_setting('test.feedback')::uuid),'applied points to exact committed revision');
do $$ begin update website_preview_revisions set artifact='{}' where id=current_setting('test.v2')::uuid; raise exception 'TEST FAILED: mutable revision'; exception when object_not_in_prerequisite_state then raise notice 'PASS immutable revision'; end $$;
select website_build_append_feedback(current_setting('test.principal')::jsonb,current_setting('test.ref')::jsonb,'{"idempotencyKey":"f2","text":"Ny ändring","inputSource":"voice","viewedRevisionId":null}');
update runs set status='failed' where id=(select current_run_id from website_build_sessions where id=current_setting('test.session')::uuid);
select website_build_test_assert((select status='failed' and active_preview_revision_id=current_setting('test.v2')::uuid from website_build_sessions where id=current_setting('test.session')::uuid),'failed run preserves latest preview');
select website_build_test_assert(not has_function_privilege('authenticated','public.website_build_create(jsonb,jsonb)','execute'),'client cannot execute mutators');
select website_build_test_assert(not has_table_privilege('authenticated','website_build_feedback','insert'),'client cannot forge feedback');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',false);
set role authenticated;
select public.website_build_test_assert((select count(*)=0 from website_build_sessions),'other project RLS denies session');
select public.website_build_test_assert((select count(*)=0 from website_preview_revisions),'other project RLS denies artifact');
reset role;
select set_config('test.cancelref',jsonb_build_object('projectId','10000000-0000-4000-8000-000000000001','sessionId',website_build_create(current_setting('test.principal')::jsonb,current_setting('test.create')::jsonb||'{"idempotencyKey":"pending-cancel"}')->>'sessionId')::text,false);
select website_build_control(current_setting('test.principal')::jsonb,current_setting('test.cancelref')::jsonb,'{"action":"cancel","idempotencyKey":"cancel-1"}');
select website_build_test_assert((select status='cancelled' and current_run_id is null and control_requested is null from website_build_sessions where id=(current_setting('test.cancelref')::jsonb->>'sessionId')::uuid),'pending cancellation has a terminal acknowledgement');
create function public.website_build_test_race_setup() returns jsonb language plpgsql as $$ declare v jsonb; s website_build_sessions; r runs; begin v:=website_build_create('{"userId":"20000000-0000-4000-8000-000000000001","allowedProjectIds":["10000000-0000-4000-8000-000000000001"]}'::jsonb,'{"projectId":"10000000-0000-4000-8000-000000000001","agentId":"40000000-0000-4000-8000-000000000001","conversationId":"50000000-0000-4000-8000-000000000001","brief":"Race test"}'::jsonb||jsonb_build_object('idempotencyKey','race-'||gen_random_uuid())); select * into s from website_build_sessions where id=(v->>'sessionId')::uuid; update runs set status='running',claim_id=gen_random_uuid(),lease_until=now()+interval '5 minutes' where id=s.current_run_id returning * into r; return jsonb_build_object('writer',jsonb_build_object('projectId',s.project_id,'sessionId',s.id,'runId',r.id,'claimId',r.claim_id,'generation',s.generation)); end $$;
select 'PASS session, replay, ownership, preview, pause, resume, failure and RLS';
